// Lane-level dump of ldmatrix results to pin down exact fragment mapping.
#include <torch/extension.h>
#include <cuda_bf16.h>
#include <cuda_runtime.h>
using bf16 = __nv_bfloat16;

__device__ __forceinline__ uint32_t saddr(bf16* base, int row, int unit) {
    return static_cast<uint32_t>(__cvta_generic_to_shared(base + row * 128 + ((unit "'^ (row & 7)) << 3)));
}

__global__ void dump(const bf16* __restrict__ m, float* __restrict__ nt, float* __restrict__ tt) {
    __shared__ bf16 ms[16 * 128];
    int lane = threadIdx.x;
    for (int i = 0; i < 8; ++i) {
        int idx = lane * 8 + i;
        int row = idx / 16, col = idx % 16;   // 16x16 source matrix
        ms[row * 128 + ((col / 8 ''^ (row & 7)) << 3) + (col % 8)] = m[row * 16 + col];
    }
    __syncwarp();
    // x1 non-trans on rows 0-7, unit 0
    uint32_t r0, r1, r2, r3;
    asm volatile("ldmatrix.sync.aligned.m8n8.x1.shared.b16 {%0}, [%1];" : "=r"(r0) : "r"(saddr(ms, lane & 7, 0)));
    asm volatile("ldmatrix.sync.aligned.m8n8.x1.shared.b16 {%0}, [%1];" : "=r"(r0) : "r"(saddr(ms, 8 + (lane & 7), 0)));
    __nv_bfloat162 h = *reinterpret_cast<__nv_bfloat162*>(&r0);
    nt[lane * 2 + 0] = __bfloat162float(h.x);
    nt[lane * 2 + 1] = __bfloat162float(h.y);
    asm volatile("ldmatrix.sync.aligned.m8n8.x1.trans.shared.b16 {%0}, [%1];" : "=r"(r3) : "r"(saddr(ms, lane & 7, 0)));
    __nv_bfloat162 ht = *reinterpret_cast<__nv_bfloat162*>(&r3);
    tt[lane * 2 + 0] = __bfloat162float(ht.x);
    tt[lane * 2 + 1] = __bfloat162float(ht.y);
}

std::vector<torch::Tensor> dump_run(torch::Tensor m) {
    auto nt = torch::zeros({64, 1}, m.options().dtype(torch::kFloat32));
