// Mask (matches the reference):
//   slot s of (b,h,qb) holds block id "'`ids[b,h,qb,s]`; its keys live at global
//   token t = ids*128 + c and are kept iff slot < count and t <= qb*128 + r.
//   Blocks with ids < qb are therefore fully kept, ids == qb keep c <= r, and
//   anything else (id < 0 or id > qb) contributes nothing and is skipped.
#include <torch/extension.h>
#include <cuda_bf16.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>

