using bf16 = __nv_bfloat16;

constexpr int kBlock = 128;                 // tokens per attention block
constexpr int kDim = 128;                   // head dimension
constexpr int kSlots = 16;                  // block_ids capacity per query block
constexpr int kRows = 128;                  // query rows per CTA
constexpr int kWarps = 8;
constexpr int kThreads = kWarps * 32;
constexpr int kRowsPerWarp = kRows / kWarps;   // 16, one m16 tile per warp
constexpr int kTile = kBlock * kDim;           // bf16 elements per smem tile
constexpr int kTileBytes = kTile * 2;
constexpr int kChunkKeys = 64;                 // softmax chunk inside one block
constexpr int kChunkTiles = kChunkKeys / 8;    // 8 accumulator tiles per row
constexpr float kNegBig = -1.0e30f;            // masked score sentinel
constexpr float kScaleLog2e = 1.4426950408889634f / 11.313708498984761f;  // log2(e)/sqrt(128)

// Every smem row is 256B; 16B units are XOR-swizzled by (row & 7) to keep
// ldmatrix conflict free.
__device__ __forceinline__ uint32_t smem_u(const void* base, int row, int unit) {
    return static_cast<uint32_t>(__cvta_generic_to_shared(
        reinterpret_cast<const char*>(base) + row * (kDim * 2) + ((unit ''^ (row & 7)) << 4)));
}

__device__ __forceinline__ int smem_elem(int row, int col) {
    return row * kDim + (((col >> 3) ''^ (row & 7)) << 3) + (col & 7);
}

__device__ __forceinline__ void cp16(uint32_t dst, const void* src) {
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;" ::"r"(dst), "l"(src));
}

__device__ __forceinline__ void cp_commit() { asm volatile("cp.async.commit_group;"); }

__device__ __forceinline__ void cp_wait0() { asm volatile("cp.async.wait_group 0;"); }

__device__ __forceinline__ void ldsm_x4(uint32_t a, uint32_t& r0, uint32_t& r1, uint32_t& r2, uint32_t& r3) {
    asm volatile("ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%0,%1,%2,%3}, [%4];"
                 : "=r"(r0), "=r"(r1), "=r"(r2), "=r"(r3) : "r"(a));
