using bf16 = __nv_bfloat16;

constexpr int kBlock = 128;                    // tokens per attention block
constexpr int kDim = 128;                      // head dimension
constexpr int kSlots = 16;                     // block_ids capacity
constexpr int kRows = 128;                     // query rows per CTA
constexpr int kWarps = 8;
constexpr int kThreads = kWarps * 32;
constexpr int kRowsPerWarp = kRows / kWarps;   // one m16 tile per warp
constexpr int kPitch = kDim + 8;               // smem row pitch, 16B aligned
constexpr int kChunkKeys = 64;                 // softmax chunk inside one block
constexpr int kChunkTiles = kChunkKeys / 8;
constexpr int kGroups = kChunkKeys / 16;       // 16-key groups per chunk
constexpr int kTileBytes = kBlock * kPitch * 2;
constexpr float kNegBig = -1.0e30f;
