    bf16* kt[2] = {qt + kBlock * kPitch, qt + kBlock * kPitch * 2};
    bf16* vt[2] = {qt + kBlock * kPitch * 3, qt + kBlock * kPitch * 4};

    const int count = __ldg(block_counts + (b * HQ + h) * NB + qb);
    const int* ids = block_ids + ((long)(b * HQ + h) * NB + qb) * kSlots;
    const long kvrow = (long)(b * HKV + kvh) * S * kDim;

    const long kvrow = (long)(b * HKV + kvh) * S * kDim;
    stage_tile(qt, q + ((long)(b * HQ + h) * S + qb * kBlock) * kDim, tid);

    // Bitmap of slots that contribute; the scan stays cheap inside the loop.
    int live = 0;
    for (int s = 0; s < count; ++s) {
        const int id = __ldg(ids + s);
        if (id >= 0 && id <= qb) live |= 1 << s;
    }
    int cur = (live == 0) ? -1 : __ffs(live) - 1;
    if (cur >= 0) {
        const int id = __ldg(ids + cur);
        stage_tile(kt[0], k + kvrow + (long)id * kBlock * kDim, tid);
        stage_tile(vt[0], v + kvrow + (long)id * kBlock * kDim, tid);
    }
    cp_commit();

    float o[kChunkTiles * 2][4];
#pragma unroll
    for (int j = 0; j < kChunkTiles * 2; ++j)
#pragma unroll
        for (int e = 0; e < 4; ++e) o[j][e] = 0.f;
    float lsum[2] = {0.f, 0.f};

    const int qbase = (row0 + (lane & 15)) * kPitch + qsw * 8;
    const int kbase = rl * kPitch + rsw * 8;
    const int vbase = (lane & 15) * kPitch + qsw * 8;

    int phase = 0;
    while (cur >= 0) {
        const int rest = live >> (cur + 1);
        const int nxt = rest ? __ffs(rest) + cur : -1;
        const int id = __ldg(ids + cur);
        if (nxt >= 0) {
            const int nid = __ldg(ids + nxt);
            stage_tile(kt[phase ^ 1], k + kvrow + (long)nid * kBlock * kDim, tid);
            stage_tile(vt[phase ^ 1], v + kvrow + (long)nid * kBlock * kDim, tid);
        }
        cp_commit();
        cp_wait1();
        __syncthreads();

        const bf16* ktp = kt[phase];
        const bf16* vtp = vt[phase];
        float sacc[kChunkTiles][4];
        uint32_t ap[2][kGroups][4];

        // Scores of chunk 0, then a pipelined chunk-0 softmax / chunk-1 scores /
        // chunk-0 output chain so the tensor pipe never waits on the softmax.
        if (id == qb) {
            chunk_scores<true>(ktp, qt, 0, qbase, kbase, row0, lane, mr, mc, sacc);
        } else {
            chunk_scores<false>(ktp, qt, 0, qbase, kbase, row0, lane, mr, mc, sacc);
        }
        {
            float s0[kChunkTiles][4];
#pragma unroll
            for (int j = 0; j < kChunkTiles; ++j)
#pragma unroll
                for (int e = 0; e < 4; ++e) s0[j][e] = sacc[j][e];
