        if (id == qb) {
            chunk_scores<true>(ktp, qt, kChunkKeys, qbase, kbase, row0, lane, mr, mc, sacc);
        } else {
            chunk_scores<false>(ktp, qt, kChunkKeys, qbase, kbase, row0, lane, mr, mc, sacc);
        }
        chunk_out(vtp, 0, vbase, ap[0], o);
        chunk_pack(sacc, ap[1], lsum);
