__device__ __forceinline__ uint64_t wdesc(uint32_t addr, uint32_t lbo, uint32_t sbo) {{
    return (uint64_t)((addr >> 4) & 0x3FFF) | ((uint64_t)(lbo & 0x3FFF) << 16) |
