// canonical no-swizzle K-major layout: 8x8 core matrices of contiguous 16B chunks
__device__ __forceinline__ int kInter(int r, int c) {{ return ((r >> 3) << 10) + ((c >> 3) << 6) + ((r & 7) << 3) + (c & 7); }}

__device__ __forceinline__ void wg_ss(float d[64], uint64_t da, uint64_t db) {{
    asm volatile(
        \"{{\\n.reg .pred p;\\nsetp.ne.b32 p, %66, 0;\\n\"
