__device__ __forceinline__ void stage_tile(bf16* tile, const bf16* src, int tid) {{
    const int row = tid >> 4, cu = tid & 15;
    uint32_t dst = saddr(tile + inter(row, cu << 3));
    const char* p = reinterpret_cast<const char*>(src) + ((row << 7) + (cu << 3)) * 2;
#pragma unroll
    for (int j = 0; j < 8; ++j) {{
        cp16(dst, p);
        dst += 4096;
        p += 4096;
    }}
}}

// V[key][dim] -> Vt[dim][key], one 2x2 grid of 8x8 blocks per warp instruction.
__device__ __forceinline__ void transpose_v(const bf16* src, bf16* dst, int tid) {{
    const int warp = tid >> 5, lane = tid & 31, which = lane >> 3, row = lane & 7;
#pragma unroll
    for (int i = 0; i < 8; ++i) {{
        const int grid = warp * 8 + i, a = grid >> 3, b = grid & 7;
        const int kb = 2 * a + ((which >> 1) & 1), db = 2 * b + (which & 1);
        uint32_t r[4];
        ldsm_x4_t(saddr(src + inter(8 * kb + row, 8 * db)), r);
        stsm_x4(saddr(dst + inter(8 * db + row, 8 * kb)), r);
    }}
}}

