// Masked lanes underflow to zero, so the normaliser is a plain row sum.
template <bool DIAG>
__device__ __forceinline__ void chunk_softmax(float s[kChunkTiles][4],
                                              uint32_t ap[kChunkTiles / 2][4], int key0, int row0,
                                              int g, int lc, float l[2]) {{
#pragma unroll
    for (int j = 0; j < kChunkTiles; ++j) {{
