            if (c0 + 1 > r0) s[j][1] = kNegBig;
            if (c0 > r1) s[j][2] = kNegBig;
            if (c0 + 1 > r1) s[j][3] = kNegBig;
        }}
#pragma unroll
        for (int e = 0; e < 4; ++e) {{
