            l[e >> 1] += s[j][e];
        }}
    }}
#pragma unroll
    for (int j = 0; j < kChunkTiles / 2; ++j) {{
        ap[j][0] = pack2(s[2 * j][0], s[2 * j][1]);
        ap[j][1] = pack2(s[2 * j][2], s[2 * j][3]);
        ap[j][2] = pack2(s[2 * j + 1][0], s[2 * j + 1][1]);
        ap[j][3] = pack2(s[2 * j + 1][2], s[2 * j + 1][3]);
    }}
}}

