        reinterpret_cast<const bf16*>(q.data_ptr<at::BFloat16>()),
        reinterpret_cast<const bf16*>(k.data_ptr<at::BFloat16>()),
        reinterpret_cast<const bf16*>(v.data_ptr<at::BFloat16>()),
        block_ids.data_ptr<int>(), block_counts.data_ptr<int>(),
