    (void)q; (void)k; (void)v; (void)block_ids; (void)block_counts; (void)out;
    (void)S; (void)NB; (void)HQ; (void)HKV; (void)groups;
#else
    const int h = blockIdx.x, qb = blockIdx.y, b = blockIdx.z;
    const int kvh = h / groups;
