    const int g = lane >> 2, lc = lane & 3;
    const int row0 = 64 * wg + 16 * wrp;

    extern __shared__ __align__(128) bf16 smem[];
    bf16* qt = smem;
    bf16* kt[2] = {smem + kTile, smem + 2 * kTile};
    bf16* vn[2] = {smem + 3 * kTile, smem + 4 * kTile};
    bf16* vt[2] = {smem + 5 * kTile, smem + 6 * kTile};

    const int count = __ldg(block_counts + (b * HQ + h) * NB + qb);
    const int* ids = block_ids + ((b * HQ + h) * NB + qb) * kSlots;
    const long kvrow = (long)(b * HKV + kvh) * S * kDim;

    stage_tile(qt, q + ((long)(b * HQ + h) * S + qb * kBlock) * kDim, t);

    int live = 0;
    for (int s = 0; s < count; ++s) {
        const int id = __ldg(ids + s);
        if (id >= 0 && id <= qb) live |= 1 << s;
    }
    int cur = (live == 0) ? -1 : __ffs(live) - 1;
    if (cur >= 0) {
        const int id = __ldg(ids + cur);
        stage_tile(kt[0], k + kvrow + (long)id * kBlock * kDim, t);
        stage_tile(vn[0], v + kvrow + (long)id * kBlock * kDim, t);
    }
    cp_commit();

    float o[kNTiles][4];
#pragma unroll
    for (int j = 0; j < kNTiles; ++j)
#pragma unroll
        for (int e = 0; e < 4; ++e) o[j][e] = 0.f;
    float l[2] = {0.f, 0.f};

    const uint32_t qa = saddr(qt) + wg * 8 * 2048;
    int phase = 0;
    while (cur >= 0) {
        const int rest = live >> (cur + 1);
        const int nxt = rest ? __ffs(rest) + cur : -1;
        const int id = __ldg(ids + cur);

        if (nxt >= 0) {
            const int nid = __ldg(ids + nxt);
            stage_tile(kt[phase ^ 1], k + kvrow + (long)nid * kBlock * kDim, t);
            stage_tile(vn[phase ^ 1], v + kvrow + (long)nid * kBlock * kDim, t);
        }
        cp_commit();
        cp_wait1();
        __syncthreads();

        const uint32_t ka = saddr(kt[phase]);
        float s[kChunks][kChunkTiles][4];
#pragma unroll
        for (int ch = 0; ch < kChunks; ++ch)
#pragma unroll
            for (int j = 0; j < kChunkTiles; ++j)
#pragma unroll
                for (int e = 0; e < 4; ++e) s[ch][j][e] = 0.f;

        // S = Q K^T, both operands straight from shared memory.
        wg_fence();
#pragma unroll
        for (int ch = 0; ch < kChunks; ++ch)
#pragma unroll
            for (int kk = 0; kk < kSteps; ++kk)
                wg_ss64(s[ch], wdesc(qa + kk * 256), wdesc(ka + ch * 8 * 2048 + kk * 256));
        wg_commit();

