// one 128-row slot: O = softmax(Q K^T) V
__global__ void core(const bf16* __restrict__ Q, const bf16* __restrict__ K, const bf16* __restrict__ V,
                     float* __restrict__ O) {
    __shared__ __align__(16) bf16 qs[kT], ks[kT], vn[kT], vt[kT];
    int t = threadIdx.x;
    for (int i = t; i < kT; i += 256) qs[kInter(i >> 7, i & 127)] = Q[i];
    for (int i = t; i < kT; i += 256) ks[kInter(i >> 7, i & 127)] = K[i];
    for (int i = t; i < kT; i += 256) vn[kInter(i >> 7, i & 127)] = V[i];
    __syncthreads();

    // V transpose: vn[key][dim] -> vt[dim][key], 8x8 blocks via ldmatrix.trans + stmatrix
    {
        int warp = t >> 5, lane = t & 31, which = lane >> 3, row = lane & 7;
        for (int g = 0; g < 8; ++g) {
            int grid = warp * 8 + g, a = grid >> 3, b = grid & 7;
            int kb = 2 * a + ((which >> 1) & 1), db = 2 * b + (which & 1);
            uint32_t r[4];
            ldsm_x4_t(saddr(&vn[kInter(8 * kb + row, 8 * db)]), r);
            stsm_x4(saddr(&vt[kInter(8 * db + row, 8 * kb)]), r);
        }
    }
    __syncthreads();

    int wg = t >> 7, w = (t >> 5) & 3, lane = t & 31, g = lane >> 2, c = lane & 3;
    uint32_t sa = saddr(qs) + wg * 16384, sb = saddr(ks), sv = saddr(vt);
    asm volatile("wgmma.fence.sync.aligned;");
    float s[16][4];
#pragma unroll
    for (int j = 0; j < 16; ++j)
#pragma unroll
        for (int e = 0; e < 4; ++e) s[j][e] = 0.f;
#pragma unroll
    for (int kk = 0; kk < 8; ++kk) wg_ss(reinterpret_cast<float(&)[64]>(s), wdesc(sa + kk * 256, 8, 128), wdesc(sb + kk * 256, 8, 128));
    asm volatile("wgmma.commit_group.sync.aligned;");
    asm volatile("wgmma.wait_group.sync.aligned 0;");

    // exp2(s*scale), row sums, pack to A fragments (bf16)
    const float kScale = 1.4426950408889634f / 11.313708498984761f;
