            if (diag) {                                     // causal cut inside the diagonal
                const int r0 = row0 + mr, r1 = r0 + 8;
#pragma unroll
                for (int j = 0; j < kChunkTiles; ++j) {
                    const int c = key0 + 8 * j + mc;
                    if (c > r0) sacc[j][0] = kNegBig;
                    if (c + 1 > r0) sacc[j][1] = kNegBig;
