                ldsm_x4_t(smem_b(vtp, (key0 + kk * 16) * kPitch + vbase), bv[0]);
                int buf = 0;
#pragma unroll
                for (int j = 0; j < kDim / 16; ++j) {
                    if (j + 1 < kDim / 16) {
                        ldsm_x4_t(smem_b(vtp, (key0 + kk * 16) * kPitch + vbase + (j + 1) * 16), bv[buf ^ 1]);
