        if (nxt < 0) break;
        cur = nxt;
        phase ^= 1;
    }
    cp_wait0();

#pragma unroll
    for (int d = 1; d <= 2; d <<= 1) {
        lsum[0] += __shfl_xor_sync(0xffffffffu, lsum[0], d);
        lsum[1] += __shfl_xor_sync(0xffffffffu, lsum[1], d);
