        *reinterpret_cast<uint32_t*>(p0) = pack2(o[j][0] * rinv[0], o[j][1] * rinv[0]);
        *reinterpret_cast<uint32_t*>(p0 + 8 * kDim) = pack2(o[j][2] * rinv[1], o[j][3] * rinv[1]);
